package org.springframework.samples.petclinic.acceptance;

import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;

import org.springframework.test.web.servlet.ResultActions;

import tools.jackson.databind.node.ObjectNode;

/**
 * Pins the RFC7807 contract for every rejection status: 400, 409 and 429 must each return an
 * {@code application/problem+json} body carrying the four required members ({@code type},
 * {@code title}, {@code status}, {@code detail}), with {@code status} equal to the HTTP status.
 * Complements {@link AcceptanceTest}, which only exercises the 400 path.
 */
class RejectionProblemJsonTest extends AcceptanceBase {

	/** Asserts the response is a problem+json body carrying all four required members and the
	 *  given status both as the HTTP code and in the body's {@code status} member. */
	private void expectProblemJson(ResultActions result, int httpStatus) throws Exception {
		result.andExpect(status().is(httpStatus))
				.andExpect(content().contentTypeCompatibleWith("application/problem+json"))
				.andExpect(jsonPath("$.type").exists())
				.andExpect(jsonPath("$.title").exists())
				.andExpect(jsonPath("$.status").value(httpStatus))
				.andExpect(jsonPath("$.detail").exists());
	}

	@Test
	void badRequestIsProblemJson() throws Exception {
		ObjectNode invalid = ownerNode();
		invalid.remove("city");
		expectProblemJson(createOwner(invalid), 400);
	}

	@Test
	void conflictIsProblemJson() throws Exception {
		ObjectNode owner = ownerNode();
		createOwnerOk(owner);
		// Re-posting the identical owner repeats its identity key -> duplicate -> 409.
		expectProblemJson(createOwner(owner), 409);
	}

	@Test
	void tooManyRequestsIsProblemJson() throws Exception {
		createMany(EnsureUnderDailyLimit_DAILY_LIMIT);
		// One over today's per-day registration cap -> 429.
		expectProblemJson(createOwner(ownerNode()), 429);
	}

	/** The per-day create limit enforced by the create pipeline; one more create than this is rejected. */
	private static final int EnsureUnderDailyLimit_DAILY_LIMIT = 100;
}

